// Evidence: the newest evidence on the actor's live role that covers this
// act, by its kind, must be inside valid_until and its review interval.
// No pack names the acts that need evidence yet, so none recorded passes.
var current *bool
switch err := tx.QueryRow(ctx, `SELECT `+evidence("$1", "$2", "$3", "$4", "$5"),
	cmd.OrgID, cmd.ResponsibilityID, cmd.PrincipalID, cmd.Requires, cmd.Kind).Scan(&current); {
case err != nil:
	return nil, err
case current == nil:
	checks = append(checks, "evidence: not yet enforced: no evidence covers "+cmd.Kind)
case !*current:
	return nil, fmt.Errorf("%w: %s", ErrEvidenceLapsed, cmd.Kind)
